    def check_gp(a):
        """Check if list a is a geometric progression"""
        m = len(a)
        if m <= 2:
            return True  # Any sequence with 1 or 2 elements is a GP
        if all(x == 0 for x in a):
            return True  # All zeros is a GP
        if a[0] == 0:
            # If first element is 0, all others must be 0 for a GP
            return all(x == 0 for x in a)

        # Use cross-multiplication to check ratio consistency
        # For geometric progression: a[i] / a[i-1] = a[1] / a[0]
        # Equivalently: a[i] * a[0] == a[i-1] * a[1] (avoids float issues)
        r_num = a[1]
        r_den = a[0]

        for i in range(2, m):
            lhs = a[i] * r_den
            rhs = a[i-1] * r_num
            if lhs != rhs:
                return False
        return True

    # First check if it's already a GP
    if check_gp(arr):
        return "0\n"

    # Try removing each element and check if remaining is a GP
    for i in range(n):
        a = arr[:i] + arr[i+1:]
        if check_gp(a):
            return "1\n"

    return "2\n"

