def solution(input_str):
    lines = input_str.strip().split('\n')
    params1 = list(map(int, lines[0].split()))
    params2 = list(map(int, lines[1].split()))

    xp, yp, vp = params1[0], params1[1], params1[2]
    x, y, v, r = params2[0], params2[1], params2[2], params2[3]

    R = math.sqrt(xp**2 + yp**2)

    def angle(sx, sy):
        return math.atan2(sx, sy)

    def angle_diff(sx, sy, tx, ty):
        alpha = angle(sx, sy)
        beta = angle(tx, ty)
        d = beta - alpha
        while d > math.pi: d -= 2 * math.pi
        while d < -math.pi: d += 2 * math.pi
        return d

    def direct_dist(sx, sy, tx, ty):
        return math.sqrt((tx - sx)**2 + (ty - sy)**2)

    def planet_pos(t):
        if R <= 0:
            return xp, yp
        theta = angle(xp, yp) + (vp / R) * t
        return R * math.cos(theta), R * math.sin(theta)

    def path_distance(sx, sy, tx, ty, rad):
        if sx**2 + sy**2 <= rad**2 or tx**2 + ty**2 <= rad**2:
            return float('inf')

        dist_s = direct_dist(0, 0, sx, sy)
        dist_t = direct_dist(0, 0, tx, ty)
        theta_diff = angle_diff(sx, sy, tx, ty)
        while theta_diff > math.pi: theta_diff -= 2 * math.pi
        while theta_diff < -math.pi: theta_diff += 2 * math.pi

        tan_s = math.sqrt(dist_s**2 - rad**2)
        tan_t = math.sqrt(dist_t**2 - rad**2)

        return tan_s + tan_t + rad * abs(theta_diff)

    def feasible(t):
        tx, ty = planet_pos(t)
        md = path_distance(x, y, tx, ty, r)
        return md <= v * t

    low, high = 0.0, 1e15
    ans = 0.0

    while high - low > 1e-9:
        mid = (low + high) / 2
        if feasible(mid):
            ans = mid
            high = mid
        else:
            low = mid

    return f"{ans:.10f}"

