def solution(input_str):
    # This is a competitive programming problem. The solution uses maximum independent set.
    # Based on the problem: in each segment, at most one friend can be happy.
    # If two friends appear in the same segment, they conflict.
    # We want maximum subset of non-conflicting friends.

    lines = input_str.strip().split('\n')
