        parts = line.split()
        if parts[0] == '1':
            segments.append(current_segment)
            current_segment = []
        elif parts[0] == '2' and len(parts) > 1:
            current_segment.append(parts[1])
    if current_segment:
        segments.append(current_segment)

    # If no segments (edge case), return 1 since guaranteed at least one visit
    if not segments:
        return "1"

    # Build conflict matrix: adj[i][j] = 1 if friend i and friend j appear in same segment
    def build_adj():
        adj = {}
        all_friends = set()
        for seg in segments:
            for f in seg:
                all_friends.add(f)
        all_friends = list(all_friends)
        n_friends = len(all_friends)
        friend_to_idx = {f: i for i, f in enumerate(all_friends)}

        adj = [[0] * n_friends for _ in range(n_friends)]

        for seg in segments:
            for f in seg:
                if f in friend_to_idx:
                    i = friend_to_idx[f]
                    for other in seg:
                        if other in friend_to_idx:
                            j = friend_to_idx[other]
                            if i != j:
                                adj[i][j] = 1
                                adj[j][i] = 1
        return adj, friend_to_idx

    # Maximum independent set using efficient recursive search
    def max_independent_set(adj, n):
        results = [0]

        def backtrack(mask, independent_count):
            if independent_count >= results[0]:
                results[0] = independent_count
            else:
                return

            # Find next node to consider
            remaining_count = popcount(mask | ~((1 << n) - 1))
            if remaining_count == 0:
                return

            # Greedy: pick smallest node not in mask
            for i in range(n):
                if not ((mask >> i) & 1):
                    # Try including node i
                    new_mask = mask | (1 << i)
                    valid = True
                    for j in range(n):
                        if ((new_mask >> j) & 1) and adj[i][j]:
                            valid = False
                            break

                    if valid:
                        backtrack(new_mask, independent_count + 1)
                    break

            backtrack(mask, independent_count)

        def popcount(x):
            c = 0
            while x:
                x &= x - 1
                c += 1
            return c

        backtrack(0, 0)
        return results[0]

    adj, _ = build_adj()
    n_friends = len(adj)
    if n_friends == 0:
        return "1"

    result = max_independent_set(adj, n_friends)
    return str(result)

