    adj = [[] for _ in range(len(roads))]
    road_count = len(roads)

    def intersects(a1, b1, a2, b2):
        """Check if two chords (a1,b1) and (a2,b2) intersect when both on same side"""
        a1, b1 = sorted((a1, b1))
        a2, b2 = sorted((a2, b2))

        # Check if endpoints alternate (a1 < a2 < b1 < b2 or a2 < a1 < b2 < b1)
        endpoints = sorted([a1, b1, a2, b2])
        positions = {}
        pos = 0
        for p in endpoints:
            positions[p] = pos
            pos += 1

        # Check alternating: a1,a2 should be at positions 0,1 or 1,2 or 2,3 but NOT at 0,2 or 0,3 or 1,3
        if a1 not in positions or a2 not in positions:
            return False

        # They intersect if endpoints are in alternating order
        return (pos[a1] < pos[a2] < pos[b1] < pos[b2]) or (pos[a2] < pos[a1] < pos[b2] < pos[b1])

    for i in range(road_count):
        for j in range(i + 1, road_count):
            a1, b1 = sorted(roads[i])
            a2, b2 = sorted(roads[j])
            if not (a1 in [a2, b2] or b1 in [a2, b2]):  # Don't count shared endpoints as crossing
                if intersects(a1, b1, a2, b2):
                    adj[i].append(j)
                    adj[j].append(i)

